def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError

    batches = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError

        if current_weight + weight <= limit:
            current_batch.append(name)
            current_weight += weight
        else:
            if current_batch:
                batches.append(current_batch)
            current_batch = [name]
            current_weight = weight

    if current_batch:
        batches.append(current_batch)

    return batches

import re

def parse_env(text):
    env = {}
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid environment line: {line}")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        if not key_pattern.fullmatch(key):
            raise ValueError(f"Invalid environment key: {key}")
        env[key] = value
    return env

def parse_sse(chunks):
    text = b"".join(chunks).decode("utf-8")
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    if text.endswith("\n"):
        lines.pop()

    events = []
    event_data_lines = None
    stop = False

    for line in lines:
        if stop:
            break

        if line == "":
            if event_data_lines is not None:
                data_str = "\n".join(event_data_lines)
                event_data_lines = None
                if data_str == "[DONE]":
                    stop = True
                    break
                events.append(data_str)
            continue

        if line.startswith(":"):
            continue

        if ":" in line:
            field, value = line.split(":", 1)
            if field.strip().lower() == "data":
                if value.startswith(" "):
                    value = value[1:]
                if event_data_lines is None:
                    event_data_lines = []
                event_data_lines.append(value)

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("retry_delay arguments must be nonnegative")

    if base == 0 or cap == 0:
        return 0.0

    threshold = math.log2(cap) - math.log2(base)
    if attempt > threshold:
        return float(cap)

    return float(math.ldexp(base, attempt))

def fifo_admit(active, queued, budget, slots):
    if any(r > budget for r in queued):
        raise ValueError("Queued reservation exceeds budget")

    token_remaining = budget - sum(active)
    slot_remaining = slots - len(active)
    admitted = []

    for req in queued:
        if req <= token_remaining and len(admitted) < slot_remaining:
            admitted.append(req)
            token_remaining -= req
        else:
            break

    remaining = queued[len(admitted):]
    return (admitted, remaining)
